-- KEYMART: complete import for an EMPTY MySQL 8 database (Railway, XAMPP/phpMyAdmin, MySQL Workbench, mysql CLI).
--
--   mysql -h <host> -P <port> -u <user> -p <database> < backend/database/railway_import.sql
--
-- Contents: the schema (database/migrations/001-007 in order, unchanged), the migration ledger (so the app's migrator does not
-- repeat them), and the reference/demo data written by the seeder: platforms, regions, sellers, products, offers, deals,
-- product statistics, banners, homepage blocks and the two demo accounts (docs/EMAIL.md).
-- NOT included: game_keys. Keys are encrypted with YOUR KEY_ENCRYPTION_KEY, so they must be created by the app: after the import run
-- `php bin/seed.php` once with your production variables (docs/RAILWAY.md, step 5). Until then every offer shows as out of stock.
--
-- Safe by construction: plain CREATE TABLE (no DROP; only the ledger table uses IF NOT EXISTS), so importing into a database that already has these tables
-- fails on the first statement instead of changing anything. Regenerate with docs/RAILWAY.md "Regenerating this file".

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+00:00';

-- ===== schema: 001_users_auth.sql =====
CREATE TABLE users (
    id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    email         VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    display_name  VARCHAR(50)  NOT NULL,
    token_version INT UNSIGNED NOT NULL DEFAULT 0, -- bump to revoke every JWT of this user
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per login attempt; the rate limiter counts recent failures.
CREATE TABLE login_attempts (
    id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    ip           VARCHAR(45) NOT NULL,
    email_hash   CHAR(64)    NOT NULL, -- sha256 of the lower-cased email: no raw emails of strangers kept
    succeeded    TINYINT(1)  NOT NULL DEFAULT 0,
    attempted_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_attempts_ip_time (ip, attempted_at),
    KEY idx_attempts_email_time (email_hash, attempted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== schema: 002_catalog.sql =====
CREATE TABLE platforms (
    id   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(40) NOT NULL,
    name VARCHAR(60) NOT NULL,
    UNIQUE KEY uq_platforms_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE regions (
    id   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug VARCHAR(40) NOT NULL,
    name VARCHAR(60) NOT NULL,
    UNIQUE KEY uq_regions_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sellers (
    id     INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name   VARCHAR(80)  NOT NULL,
    rating DECIMAL(2,1) NOT NULL, -- 0.0 - 5.0
    UNIQUE KEY uq_sellers_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE products (
    id           INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug         VARCHAR(160) NOT NULL,
    name         VARCHAR(160) NOT NULL,
    name_norm    VARCHAR(160) NOT NULL, -- lower-cased, accent-free name used by search
    description  TEXT         NOT NULL,
    genre        VARCHAR(40)  NOT NULL,
    publisher    VARCHAR(80)  NOT NULL,
    release_date DATE         NOT NULL,
    platform_id  SMALLINT UNSIGNED NOT NULL,
    region_id    SMALLINT UNSIGNED NOT NULL,
    cover_svg    MEDIUMTEXT   NOT NULL, -- generated cover, served by /api/images/products/{slug}.svg
    created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_products_slug (slug),
    KEY idx_products_platform (platform_id),
    KEY idx_products_region (region_id),
    KEY idx_products_release (release_date),
    KEY idx_products_name_norm (name_norm),
    CONSTRAINT fk_products_platform FOREIGN KEY (platform_id) REFERENCES platforms (id),
    CONSTRAINT fk_products_region   FOREIGN KEY (region_id)   REFERENCES regions (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE offers (
    id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    product_id  INT UNSIGNED NOT NULL,
    seller_id   INT UNSIGNED NOT NULL,
    price_cents INT UNSIGNED NOT NULL,
    currency    CHAR(3)      NOT NULL DEFAULT 'EUR',
    active      TINYINT(1)   NOT NULL DEFAULT 1,
    UNIQUE KEY uq_offers_product_seller (product_id, seller_id),
    KEY idx_offers_price (product_id, price_cents),
    CONSTRAINT fk_offers_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT fk_offers_seller  FOREIGN KEY (seller_id)  REFERENCES sellers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Deals are their own source for the homepage "deals" block: an offer with a crossed-out price.
CREATE TABLE deals (
    id                   INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    offer_id             INT UNSIGNED NOT NULL,
    original_price_cents INT UNSIGNED NOT NULL,
    discount_pct         TINYINT UNSIGNED NOT NULL,
    ends_at              DATETIME NULL, -- NULL = ongoing
    UNIQUE KEY uq_deals_offer (offer_id),
    CONSTRAINT fk_deals_offer FOREIGN KEY (offer_id) REFERENCES offers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Own source for the "best sellers" block and for popularity sorting.
CREATE TABLE product_stats (
    product_id INT UNSIGNED NOT NULL PRIMARY KEY,
    units_sold INT UNSIGNED NOT NULL DEFAULT 0,
    view_count INT UNSIGNED NOT NULL DEFAULT 0,
    popularity INT UNSIGNED NOT NULL DEFAULT 0,
    KEY idx_stats_popularity (popularity),
    KEY idx_stats_sold (units_sold),
    CONSTRAINT fk_stats_product FOREIGN KEY (product_id) REFERENCES products (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per sellable key. key_enc is libsodium-encrypted; key_hash (sha256 of the plain key)
-- lets the seeder be idempotent without ever decrypting. order_id gets its FK in the checkout migration.
CREATE TABLE game_keys (
    id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    offer_id       INT UNSIGNED NOT NULL,
    key_enc        VARCHAR(255) NOT NULL,
    key_hash       CHAR(64)     NOT NULL,
    status         ENUM('available','reserved','sold') NOT NULL DEFAULT 'available',
    order_id       BIGINT UNSIGNED NULL,
    reserved_until DATETIME NULL,
    UNIQUE KEY uq_keys_hash (key_hash),
    KEY idx_keys_offer_status (offer_id, status, id),
    KEY idx_keys_reserved (status, reserved_until),
    CONSTRAINT fk_keys_offer FOREIGN KEY (offer_id) REFERENCES offers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== schema: 003_homepage.sql =====
CREATE TABLE banners (
    id         INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug       VARCHAR(60)  NOT NULL,
    title      VARCHAR(120) NOT NULL,
    subtitle   VARCHAR(200) NOT NULL,
    cta_label  VARCHAR(40)  NOT NULL,
    href       VARCHAR(200) NOT NULL,
    image_svg  MEDIUMTEXT   NOT NULL, -- served by /api/images/banners/{slug}.svg
    position   SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    active     TINYINT(1)   NOT NULL DEFAULT 1,
    UNIQUE KEY uq_banners_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- The homepage layout lives in the database: the frontend only renders what GET /api/home/layout returns.
CREATE TABLE home_blocks (
    id       INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    slug     VARCHAR(40)  NOT NULL,  -- banner, best_sellers, deals, new_releases
    type     VARCHAR(40)  NOT NULL,  -- frontend component: hero | carousel
    title    VARCHAR(120) NOT NULL,
    endpoint VARCHAR(120) NOT NULL,  -- the block's own data source
    position SMALLINT UNSIGNED NOT NULL,
    enabled  TINYINT(1)   NOT NULL DEFAULT 1,
    config   JSON NULL,
    UNIQUE KEY uq_home_blocks_slug (slug),
    KEY idx_home_blocks_position (position)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== schema: 004_catalog_indexes.sql =====
-- Genre is a filter and a facet (GROUP BY genre).
CREATE INDEX idx_products_genre ON products (genre);

-- ===== schema: 005_cart_orders.sql =====
-- Server-side cart: one row per (user, offer). Prices are never stored here, they are read live from offers.
CREATE TABLE cart_items (
    id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id    BIGINT UNSIGNED NOT NULL,
    offer_id   INT UNSIGNED NOT NULL,
    qty        TINYINT UNSIGNED NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_cart_user_offer (user_id, offer_id),
    CONSTRAINT fk_cart_user  FOREIGN KEY (user_id)  REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_cart_offer FOREIGN KEY (offer_id) REFERENCES offers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- pending  = keys reserved, waiting for payment (until reserved_until)
-- paid     = payment confirmed by Stripe's webhook, keys sold
-- failed / expired / canceled = keys released
-- refund_needed = money was taken but the keys could not be delivered; refunded = we returned it
CREATE TABLE orders (
    id                       BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id                  BIGINT UNSIGNED NOT NULL,
    status                   ENUM('pending','paid','failed','expired','canceled','refund_needed','refunded') NOT NULL DEFAULT 'pending',
    currency                 CHAR(3)      NOT NULL,
    total_cents              INT UNSIGNED NOT NULL,
    stripe_payment_intent_id VARCHAR(255) NULL,
    reserved_until           DATETIME     NOT NULL,   -- UTC
    paid_at                  DATETIME     NULL,       -- UTC
    failure_reason           VARCHAR(255) NULL,
    created_at               TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_orders_payment_intent (stripe_payment_intent_id),
    KEY idx_orders_user_created (user_id, created_at, id),
    KEY idx_orders_status_reserved (status, reserved_until),
    CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- A snapshot: name and price as they were when the order was created, whatever the catalog does later.
CREATE TABLE order_items (
    id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    order_id         BIGINT UNSIGNED NOT NULL,
    offer_id         INT UNSIGNED NOT NULL,
    product_id       INT UNSIGNED NOT NULL,
    product_slug     VARCHAR(160) NOT NULL,
    product_name     VARCHAR(160) NOT NULL,
    seller_name      VARCHAR(80)  NOT NULL,
    unit_price_cents INT UNSIGNED NOT NULL,
    qty              TINYINT UNSIGNED NOT NULL,
    UNIQUE KEY uq_order_items_offer (order_id, offer_id),
    CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders (id),
    CONSTRAINT fk_order_items_offer FOREIGN KEY (offer_id) REFERENCES offers (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every Stripe event is processed once: the primary key is the dedupe.
CREATE TABLE stripe_events (
    event_id     VARCHAR(255) NOT NULL PRIMARY KEY,
    type         VARCHAR(100) NOT NULL,
    processed_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE game_keys ADD CONSTRAINT fk_keys_order FOREIGN KEY (order_id) REFERENCES orders (id);
CREATE INDEX idx_keys_order ON game_keys (order_id);

-- ===== schema: 006_rate_limits.sql =====
-- Fixed-window request counters for the abuse limits (App\Support\RateLimiter): one row per (limit name, who, window).
-- The primary key makes "count this request" a single atomic INSERT ... ON DUPLICATE KEY UPDATE, with no read-then-write race.
CREATE TABLE rate_limits (
    bucket       VARCHAR(40)  NOT NULL,   -- which limit: register, checkout, search
    subject      VARCHAR(64)  NOT NULL,   -- who: client IP, or user id
    window_start INT UNSIGNED NOT NULL,   -- unix time the window began (a multiple of the window length)
    hits         INT UNSIGNED NOT NULL DEFAULT 1,
    PRIMARY KEY (bucket, subject, window_start),
    KEY idx_rate_limits_old (window_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== schema: 007_email_verification.sql =====
-- NULL = the address has not been confirmed yet. Existing accounts stay unverified until they use a link.
ALTER TABLE users ADD COLUMN email_verified_at DATETIME NULL DEFAULT NULL AFTER display_name;

-- Only the SHA-256 of a token is stored: a copy of this table cannot be used to verify anybody.
CREATE TABLE email_verifications (
    id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id    BIGINT UNSIGNED NOT NULL,
    token_hash CHAR(64)  NOT NULL,
    expires_at DATETIME  NOT NULL,
    used_at    DATETIME  NULL DEFAULT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_email_verifications_token (token_hash),
    KEY idx_email_verifications_user (user_id),
    CONSTRAINT fk_email_verifications_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ===== migration ledger (same table the app's migrator creates) =====
CREATE TABLE IF NOT EXISTS schema_migrations (
    filename VARCHAR(190) NOT NULL PRIMARY KEY,
    applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
;

-- ===== data (parents before children) =====
/*!40103 SET @OLD_TIME_ZONE=@@TIME_ZONE */;
/*!40103 SET TIME_ZONE='+00:00' */;
/*!40014 SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0 */;
/*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */;
/*!40111 SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0 */;










/*!40103 SET TIME_ZONE=@OLD_TIME_ZONE */;

/*!40101 SET SQL_MODE=@OLD_SQL_MODE */;
/*!40014 SET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS */;
/*!40111 SET SQL_NOTES=@OLD_SQL_NOTES */;


SET FOREIGN_KEY_CHECKS = 1;
