(2,'electric-canyon-xbox-europe','Electric Canyon','electric canyon','Electric Canyon is a simulation game from Redwood Collective. A calm, detailed sandbox with systems you can master for hundreds of hours.','Simulation','Redwood Collective','2018-01-05',3,2,'<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 533\" width=\"400\" height=\"533\" role=\"img\" aria-label=\"Electric Canyon\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"hsl(255,70%,38%)\"/><stop offset=\"1\" stop-color=\"hsl(309,75%,22%)\"/></linearGradient><linearGradient id=\"s\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#000\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#000\" stop-opacity=\"0.75\"/></linearGradient><style>.t{font:800 34px Montserrat,Arial,sans-serif;fill:#fff}</style></defs><rect width=\"400\" height=\"533\" fill=\"url(#g)\"/><polygon points=\"254,267 334,302 294,347\" fill=\"hsl(309,90%,70%)\" opacity=\"0.25\"/><circle cx=\"98\" cy=\"272\" r=\"66\" fill=\"hsl(309,85%,65%)\" opacity=\"0.18\"/><polygon points=\"1,399 211,402 106,609\" fill=\"hsl(255,90%,70%)\" opacity=\"0.15\"/><polygon points=\"166,326 338,351 252,498\" fill=\"hsl(309,90%,70%)\" opacity=\"0.26\"/><text x=\"200\" y=\"260\" text-anchor=\"middle\" font-family=\"Montserrat,Arial,sans-serif\" font-weight=\"800\" font-size=\"220\" fill=\"#fff\" opacity=\"0.10\">E</text><rect y=\"300\" width=\"400\" height=\"233\" fill=\"url(#s)\"/><text x=\"24\" y=\"395\" class=\"t\">Electric Canyon</text></svg>','2026-11-10 13:43:30'),
