(4,'forgotten-drift-epic-games-united-states','Forgotten Drift','forgotten drift','Forgotten Drift is a simulation game from Ironvale Software. Design, manage and optimise in a world that reacts to every decision.','Simulation','Ironvale Software','2026-01-05',5,3,'<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 533\" width=\"400\" height=\"533\" role=\"img\" aria-label=\"Forgotten Drift\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"hsl(283,70%,38%)\"/><stop offset=\"1\" stop-color=\"hsl(347,75%,22%)\"/></linearGradient><linearGradient id=\"s\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#000\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#000\" stop-opacity=\"0.75\"/></linearGradient><style>.t{font:800 34px Montserrat,Arial,sans-serif;fill:#fff}</style></defs><rect width=\"400\" height=\"533\" fill=\"url(#g)\"/><polygon points=\"342,389 676,376 509,723\" fill=\"hsl(347,90%,70%)\" opacity=\"0.19\"/><polygon points=\"95,-10 253,-13 174,148\" fill=\"hsl(347,90%,70%)\" opacity=\"0.25\"/><polygon points=\"119,300 445,284 282,626\" fill=\"hsl(347,90%,70%)\" opacity=\"0.30\"/><circle cx=\"242\" cy=\"372\" r=\"100\" fill=\"hsl(347,85%,65%)\" opacity=\"0.24\"/><polygon points=\"26,396 138,397 82,508\" fill=\"hsl(283,90%,70%)\" opacity=\"0.17\"/><text x=\"200\" y=\"260\" text-anchor=\"middle\" font-family=\"Montserrat,Arial,sans-serif\" font-weight=\"800\" font-size=\"220\" fill=\"#fff\" opacity=\"0.10\">F</text><rect y=\"300\" width=\"400\" height=\"233\" fill=\"url(#s)\"/><text x=\"24\" y=\"395\" class=\"t\">Forgotten Drift</text></svg>','2026-11-10 13:43:30'),
