(117,'gilded-rift-steam-europe','Gilded Rift','gilded rift','Gilded Rift is a platformer game from Foxglove Works. Precise jumps, hidden routes and a soundtrack that keeps you moving.','Platformer','Foxglove Works','2022-12-10',1,2,'<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 533\" width=\"400\" height=\"533\" role=\"img\" aria-label=\"Gilded Rift\"><defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"hsl(148,70%,38%)\"/><stop offset=\"1\" stop-color=\"hsl(223,75%,22%)\"/></linearGradient><linearGradient id=\"s\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#000\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#000\" stop-opacity=\"0.75\"/></linearGradient><style>.t{font:800 34px Montserrat,Arial,sans-serif;fill:#fff}</style></defs><rect width=\"400\" height=\"533\" fill=\"url(#g)\"/><polygon points=\"-40,372 106,429 33,518\" fill=\"hsl(148,90%,70%)\" opacity=\"0.22\"/><polygon points=\"31,394 275,396 153,638\" fill=\"hsl(148,90%,70%)\" opacity=\"0.25\"/><polygon points=\"124,391 460,381 292,727\" fill=\"hsl(223,90%,70%)\" opacity=\"0.26\"/><circle cx=\"138\" cy=\"48\" r=\"142\" fill=\"hsl(148,85%,65%)\" opacity=\"0.25\"/><text x=\"200\" y=\"260\" text-anchor=\"middle\" font-family=\"Montserrat,Arial,sans-serif\" font-weight=\"800\" font-size=\"220\" fill=\"#fff\" opacity=\"0.10\">G</text><rect y=\"300\" width=\"400\" height=\"233\" fill=\"url(#s)\"/><text x=\"24\" y=\"395\" class=\"t\">Gilded Rift</text></svg>','2026-11-10 13:43:30'),
